import { Component, OnInit } from '@angular/core';
import { DatePipe } from '@angular/common';
import { CommonModule } from '@angular/common';
import {HttpClient} from "@angular/common/http";
import pdfMake from 'pdfmake/build/pdfmake';
import pdfFonts from 'pdfmake/build/vfs_fonts';
import * as htmlTopdfmake from 'html-to-pdfmake'
import {getHtmlTagDefinition} from "@angular/compiler";
pdfMake.vfs = pdfFonts.pdfMake.vfs;

@Component({
  selector: 'app-reporte-ventas',
  standalone: true,
  imports: [CommonModule],
  providers: [DatePipe],
  templateUrl: './reporte-ventas.component.html',
  styleUrl: './reporte-ventas.component.css'
})
export class ReporteVentasComponent {

  arregloDatos: vistaVentas[] = []

  constructor(private http: HttpClient, private datePipe: DatePipe) {}

  ngOnInit(): void {
    this.obtenerDatos();
  }

  obtenerDatos() {

    this.arregloDatos = []
    const url = 'http://www.alimentoscarnisimasa.somee.com/api/VistaVentas';

    this.http.get<vistaVentasResponse>(url).subscribe(
      (response) => {
        if (Array.isArray(response.data)) {
          this.arregloDatos = response.data;
        }
      },
      (error) => {
        console.error('Error al obtener datos:', error);
      }
    );
  }

  formatearFecha(date: string): string {
    let fecha_ = new Date(date)
    let dia =  fecha_.getDate()
    let mes = ""
    if (fecha_.getMonth() < 9){
      mes = "0" + (fecha_.getMonth() + 1)
    }else {
      mes = (fecha_.getMonth() + 1) + ''
    }
    let anio = fecha_.getFullYear()

    let fechaFormateada = `${dia}-${mes}-${anio}`

    return fechaFormateada
  }

  obtenerFechaActual() {
    let fechaActual = new Date();
    let fechaFormateada = this.datePipe.transform(fechaActual, 'dd-MM-yyyy');
    return(fechaFormateada);
  }

  createPDF(){
    let tabla = document.getElementById('tablaDatos')
    let html = tabla.outerHTML
    let fecha_ = this.obtenerFechaActual()

    let contentTabla = htmlTopdfmake(html)
    let fecha = { text: fecha_, style: 'fecha' };
    let encabezado = { text: 'REPORTE DE VENTAS', style: 'header' };
    let otraInformacion = {text: 'Aqui se muestra un reporte de las ventas de Alimentos Carnisima S.A .', style: 'texto'};
    let piePagina = {text: 'Este reporte no tiene validez sin firma y sello del gerente', style: 'texto'};
    let content = [
      fecha,
      {
        image: 'data:image/jpeg;base64,',
        width: 70,
        alignment: 'left'
      },
      encabezado,
      otraInformacion,
      contentTabla,
      piePagina
    ]
    const pdfDefinition = {
      content: content,
      styles: {
        header: {
          fontSize: 22,
          bold: true,
          alignment: 'center',
          margin: [0, 0, 0, 0]  // ajusta los márgenes según tus necesidades
        },
        texto:{
          fontSize: 14,
          bold: false,
          margin : [0,30,30,30]
        },
        fecha:{
          fontSize: 10,
          bold: false,
          alignment: 'right'
        }
      }
    };

    const pdf = pdfMake.createPdf(pdfDefinition)
    pdf.open()
  }

}

class vistaVentas {
  idVenta: number = 0
  nombreCliente: string = ""
  productoDescripcion: string = ""
  precio: number  = 0
  fecha: string = ""
  cantidad: number = 0
  total: number = 0
}

class vistaVentasResponse{
  code: string = "";
  message: string = ""
  data: string ="";
}
